import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易辨画","description":"周易辨画 - 周易辨画","frontmatter":{"title":"周易辨画","description":"周易辨画 - 周易辨画"},"headers":[],"relativePath":"zh/classics/bianhua/001.md","filePath":"zh/classics/bianhua/001.md"}'),r={name:"zh/classics/bianhua/001.md"};function i(n,p,c,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易辨画" tabindex="-1">周易辨画 <a class="header-anchor" href="#周易辨画" aria-label="Permalink to “周易辨画”">​</a></h1><p>钦定四库全书经部一</p><p>易类提要</p><p>臣 等谨案：周易辨画四十卷，</p><p>国朝连斗山撰。斗山字叔度，颍州人。是书大旨谓一卦之义在于爻，爻画有刚有柔，因刚柔之画而立之象，即因刚柔之画而系以词。其道先在于辨画，故以为名。末有辑图一卷，则即朱子旧图而略为损益之。其说专主卦画立义，如屯之大象云四偶以次条列，如丝中贯一奇，如梭上互艮手，下动震足，如织𫟃然。经纶之象，未免穿凿太甚。然其逐卦详列互体，剖析微渺，亦颇有合于精理者。盖即爻论爻，乃能以易诠易，虽间有附会之失，而错综变化之本旨，犹可借以参观。固与高谈性道以致惝恍无归者，尚较有实际焉。乾隆四十四年八月恭校上。</p><p>总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。周易辨画提纲</p><p>看易当以象为主。系辞传曰：</p><p>「古者包牺氏之王天下也，仰则观象于天，俯则观法于地，观鸟兽之文与地之宜，近取诸身，远取诸物，于是始作八卦，以通神明之德，以类万物之情。」又曰：「易者，象也。象也者，像也。」又曰：「圣人立象以尽意。」是易之有象，乃易之所以为易也。自两汉诸儒泥于象数之学，创为五行、纳甲、飞伏之法，往往至于穿凿傅会而失其正。于是王氏弼注出，一扫而空之，至谓「得象可以忘言，得意并可以忘象」，又未免矫枉太甚。夫书不尽言，言不尽意，圣人乃立象以尽意。象苟不知，何以知言？言苟不知，何以知意？故朱子曰：「看易若是靠定象去看，便滋味长；若只恁地悬空看，也没甚意思。」又曰：「说易得其理，则象数在其中。」固是如此。然溯流以观，却须先见得象数的当下落，方说理不走作。不然，事无实证，则虚理易差也。此言可谓得读易之法。</p><p>易为卜筮之书，乃圣人吉凶与民同患，欲人趋吉避凶也。其事原为日用平常之事，其理即为日用平常之理，乃百姓可以与能者。故系辞传曰：</p><p>「易之为书也，不可远。」又曰：「无有师保，如临父母。」虽其中大无不包，精无不入，而依象明义，总宜说得浅近。愈浅近愈见精微，方是圣人觉世牖民之意。若谓易道阴阳，说入玄远幽深，先与圣人本意不符，安得与卦爻象义相符也？诸家说易，往往似因此反失。</p><p>彖乃统举一卦之义。一卦之义何在？在诸爻也。故系辞传曰：「彖者，材也。」又曰：「彖者，言乎象者也。」</p><p>「圣人有以见天下之赜，而拟诸其形容，象其物宜，是故谓之象。」夫所谓材者，即卦中刚柔之画也。所谓象者，亦即卦中刚柔之画也。因刚柔之画而立之为象，即因刚柔之画而繋之以辞也。所以曰：「知者观其彖辞，则思过半矣。」不然，彖中之画不清，即爻中之义不明，何以观其彖辞则思过半？故卦辞必要先知其所指何爻，夫然后文周之旨，分合一律，爻乃析举一爻之义。一爻之义何在？在贞与不贞也。故系辞传曰：「爻者，效天下之动者也。天下之动，贞夫一者也。」盖天下之动不一，而动之之理，不过期人皆归于贞。其得爻之贞者必吉，其得爻之不贞者必凶，故曰：「吉凶，贞胜者也。」一部周易，皆不出此一字。</p><p>初爻本一，上爻本六，其不曰一、六而曰初、上者，一不过数之开端，六亦非数之究竟，与一卦六爻之位无取也，故谓之曰「初」，则天时之履端，人事之肇基，俱于是乎在。此二爻不以一人一事言，观系辞传曰：「其初难知，其上易知，本末也。」初辞拟之，卒成之，终可知。</p><p>中四爻乃详论卦辞中之义，系辞传所谓「杂物撰德，辨是与非」者也。析而论之，一爻自为一义。总而言之，爻爻期于当位而已。其有当位而不云吉，不当位而反云吉者，义自具于「上下无常」、「刚柔相易」中，不在本爻也。至二、四同功，三、五同功之互义，则前人已言之。然汉亦有以四爻、五爻连互者，如虞氏易以豫卦初至五为比，故「利建侯」；三至上为师，故「利行师」是也。</p><p>卦变之说，自昔云然，而程子非之，朱子取之，先儒亦互有议论。窃以卦之自来，出于乾、坤，与出于否、泰，其理无二，总不外于系辞传「变动不居，周流六虚，上下无常，刚柔相易，不可为典要，惟变所适」数语。圣人既分言于各彖、爻之中，复总括于系辞传之内，其教人以读易之法，亦明且尽矣。而解者犹执本爻之辞，以为本爻解，无怪乎所解者之不可解也。汉、魏以来，如荀氏爽、虞氏翻诸家，多窥其妙，而义涉隐晦，象近穿凿，未能一归醇正。今虽偶用其意，而义必期传与经协，经与卦协，使四圣人之意若合符节，乃敢以系传之说，一为上下，一为相易，以定一解。然其道亦无他，仍即前所云贞一而已矣。盖卦中诸爻之所以上下无常、刚柔相易者，皆以求其贞者也。</p><p>易自上下无常、刚柔相易而外，又有错综与旁通之法。所谓错者，即上下两卦交易之谓也，如水雷屯、雷水解是也。所谓综者，即一卦六爻颠倒之谓也，如水雷屯、山水蒙是也。所谓旁通者，即此卦通于彼卦之谓，如比与大有是也。凡易至不可上下、不可错综处，则其义为穷，穷则旁通焉。系传所云「易穷则变，变则通」，即旁通也。卦有主爻，有应爻，有乘承。比与爻，前人论之已悉，不敢复赘。</p><p>易经二篇，传十篇，在古原自分编，自郑氏玄、王氏弼以传附经，始失其旧。但经后列传，便于检阅，故兹编尚仍之未改焉。</p>',17)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
